    Definition atr_region : ltac2:(zQ "40!ipf!sd!pf!v1>1r@2$0@1$3@1$1#k0$2P") := ltac2:(zQ "d3!sd!pf!v1!imb!iq6!ir4!ira!hg6!ind!is0!ipf!jg4!jh1&@2$4@1$0#k0@3$5@1$2@1$0#k0$1^1&@2$8~0@3$6@1$2@1$0#k0$1^1&@2$3Z@3$6@1$2@1$0#k0$1^1\1r@2$a@1$2@1$0#k0$1@2$9@2$7@2$3@2$c@2$4@1$0#k0?2sp$b~0@2$7@2$3~1@2$4@1$0#k0?2sp~2@2$9@2$7@2$3+hrpvv8~0@2$7@2$3~1+hrqgu0~2@2$9@2$7@2$3+nhkrv8~0@2$7@2$3~1+nhksg0~2@2$9@2$7@2$3+mviop0~0@2$7@2$3~1+mviop5~2@2$7@2$3+nhkki8~0@2$7@2$3~1+nhkll8~2").    (* [comment removed for export] *)

    Record atinv (m : word -> option byte) : Prop := ATI {
      ti_inv   : mem_inv asegs m;
      ti_stk   : stk asegs m (bv_unsigned sp - ATR_STACK) (bv_unsigned sp);
      ti_ac    : ACONST m;
      ti_relro : arelro_none m;
      ti_glb   : aglb_none m;
      ti_cells : cells_ok m adrv_cells;
      ti_tid   : exists t, atid_cell m t;
      ti_errno : exists e, rw_cells asegs m AERRNO [C4 e];
      ti_can   : exists can, acanary m can;
      ti_rfs   : as_RFS H [] m;
      ti_sh0   : exists shi, stack0 m (bv_unsigned sp - ATR_STACK) shi /\ bv_unsigned sp <= shi;
      ti_above : forall a : word, bv_unsigned sp <= bv_unsigned a -> m a = mem0 a;
      ti_aux   : exists B', as_rauxv_ok H m B' /\ bv_unsigned sp + 128 <= B' < 2 ^ 64;
      ti_addr  : addressable m A cap;
      ti_data  : rdn RSEGS m (Z_to_bv 64 A) (length data) = Some data;
      ti_cb    : exists junk, rw_cells asegs m A [CB (Z.to_nat cap) junk] }.

