      (* [comment removed for export] *)
      Lemma tr_printf_buf : forall (fxc : FPState) k r regs m msF mo sC LBc (Kx : TSet),
        (1 <= k <= 3)%nat ->
        as_VIS H sC msF = @mkst fxc regs (Z_to_bv 64 0xbed78) m rom -> as_AKREL H sC (mkCfg msF mo) ->
        lstate k (S k) r regs m mo sC LBc ->
        getr regs 1 = Z_to_bv 64 0xbeccc -> getr regs 11 = Z_to_bv 64 0 -> getr regs 19 = Z_to_bv 64 0 ->
        (forall regs' m' msF' mo',
           as_VIS H sC msF' = @mkst fxc regs' (Z_to_bv 64 0xbeccc) m' rom -> as_AKREL H sC (mkCfg msF' mo') ->
           lstate (S k) (S k) r regs' m' mo' sC LBc -> getr regs' 19 = Z_to_bv 64 0 ->
           realizes asegs (mkCfg msF' mo') Kx) ->
